-- ANUMATI database schema for PostgreSQL 16, as applied by `alembic upgrade head` (generated by scripts/export_contract.py).
-- 38 tables, the anumati_app runtime role, row-level security and an append-only evidence log.
-- Development uses the same models on SQLite.

BEGIN;

CREATE TABLE alembic_version (
    version_num VARCHAR(32) NOT NULL, 
    CONSTRAINT alembic_version_pkc PRIMARY KEY (version_num)
);

-- Running upgrade  -> 0001_baseline

CREATE TABLE application_types (
    id VARCHAR(30) NOT NULL, 
    name VARCHAR(160) NOT NULL, 
    chapter VARCHAR(40) NOT NULL, 
    clause VARCHAR(80) NOT NULL, 
    summary TEXT NOT NULL, 
    steps JSON NOT NULL, 
    documents JSON NOT NULL, 
    target_days INTEGER NOT NULL, 
    PRIMARY KEY (id)
);

CREATE TABLE audit_log (
    id SERIAL NOT NULL, 
    ref VARCHAR(40) NOT NULL, 
    seq INTEGER NOT NULL, 
    at VARCHAR(19) NOT NULL, 
    actor VARCHAR(120) NOT NULL, 
    action TEXT NOT NULL, 
    payload TEXT NOT NULL, 
    prev_hash VARCHAR(64) NOT NULL, 
    hash VARCHAR(64) NOT NULL, 
    PRIMARY KEY (id), 
    UNIQUE (ref, seq)
);

CREATE INDEX ix_audit_log_hash ON audit_log (hash);

CREATE INDEX ix_audit_log_ref ON audit_log (ref);

CREATE TABLE calendar_events (
    id VARCHAR(20) NOT NULL, 
    label VARCHAR(200) NOT NULL, 
    date DATE NOT NULL, 
    end_date DATE, 
    kind VARCHAR(12) NOT NULL, 
    clause VARCHAR(60), 
    revised_from DATE, 
    revision_reason TEXT, 
    PRIMARY KEY (id)
);

CREATE TABLE experts (
    id VARCHAR(10) NOT NULL, 
    name VARCHAR(120) NOT NULL, 
    city VARCHAR(80) NOT NULL, 
    region VARCHAR(8) NOT NULL, 
    specialisation VARCHAR(80) NOT NULL, 
    load INTEGER NOT NULL, 
    max_load INTEGER NOT NULL, 
    linked_institutions JSON NOT NULL, 
    available BOOLEAN NOT NULL, 
    PRIMARY KEY (id)
);

CREATE TABLE feedback (
    id SERIAL NOT NULL, 
    page VARCHAR(200) NOT NULL, 
    helpful BOOLEAN NOT NULL, 
    comment TEXT NOT NULL, 
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
    PRIMARY KEY (id)
);

CREATE TABLE glossary (
    key VARCHAR(40) NOT NULL, 
    "full" VARCHAR(120) NOT NULL, 
    meaning TEXT NOT NULL, 
    clause VARCHAR(40), 
    aliases JSON NOT NULL, 
    PRIMARY KEY (key)
);

CREATE TABLE idempotency_keys (
    key VARCHAR(160) NOT NULL, 
    request_hash VARCHAR(64) NOT NULL, 
    status_code INTEGER, 
    response JSON, 
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
    PRIMARY KEY (key)
);

CREATE INDEX ix_idempotency_keys_created_at ON idempotency_keys (created_at);

CREATE TABLE inspection_draws (
    id SERIAL NOT NULL, 
    drand_round INTEGER NOT NULL, 
    randomness VARCHAR(64) NOT NULL, 
    source VARCHAR(40) NOT NULL, 
    k INTEGER NOT NULL, 
    weights JSON NOT NULL, 
    chosen JSON NOT NULL, 
    drawn_by VARCHAR(120) NOT NULL, 
    drawn_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
    PRIMARY KEY (id)
);

CREATE TABLE key_values (
    key VARCHAR(60) NOT NULL, 
    value JSON NOT NULL, 
    PRIMARY KEY (key)
);

CREATE TABLE notices (
    id VARCHAR(20) NOT NULL, 
    title VARCHAR(300) NOT NULL, 
    date DATE NOT NULL, 
    audience VARCHAR(20) NOT NULL, 
    category VARCHAR(20) NOT NULL, 
    summary TEXT NOT NULL, 
    PRIMARY KEY (id)
);

CREATE TABLE notifications (
    id SERIAL NOT NULL, 
    audience VARCHAR(12) NOT NULL, 
    institution_id VARCHAR(20), 
    region VARCHAR(8), 
    title TEXT NOT NULL, 
    tone VARCHAR(8) NOT NULL, 
    ref VARCHAR(20), 
    channels JSON NOT NULL, 
    delivery JSON NOT NULL, 
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
    read BOOLEAN NOT NULL, 
    PRIMARY KEY (id)
);

CREATE INDEX ix_notifications_created_at ON notifications (created_at);

CREATE INDEX ix_notifications_institution_id ON notifications (institution_id);

CREATE TABLE regions (
    id VARCHAR(8) NOT NULL, 
    name VARCHAR(80) NOT NULL, 
    office VARCHAR(80) NOT NULL, 
    states JSON NOT NULL, 
    PRIMARY KEY (id)
);

CREATE TABLE rule_versions (
    id SERIAL NOT NULL, 
    version VARCHAR(20) NOT NULL, 
    "table" JSON NOT NULL, 
    targets JSON NOT NULL, 
    status VARCHAR(12) NOT NULL, 
    author VARCHAR(120) NOT NULL, 
    approver VARCHAR(120), 
    reason TEXT NOT NULL, 
    effective_from DATE, 
    tests_passed INTEGER NOT NULL, 
    tests_total INTEGER NOT NULL, 
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
    published_at TIMESTAMP WITHOUT TIME ZONE, 
    PRIMARY KEY (id), 
    UNIQUE (version)
);

CREATE TABLE saved_views (
    id SERIAL NOT NULL, 
    user_id VARCHAR(40) NOT NULL, 
    name VARCHAR(80) NOT NULL, 
    query VARCHAR(300) NOT NULL, 
    PRIMARY KEY (id)
);

CREATE INDEX ix_saved_views_user_id ON saved_views (user_id);

CREATE TABLE status_checks (
    id SERIAL NOT NULL, 
    service VARCHAR(60) NOT NULL, 
    at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
    ok BOOLEAN NOT NULL, 
    latency_ms INTEGER NOT NULL, 
    PRIMARY KEY (id)
);

CREATE INDEX ix_status_checks_at ON status_checks (at);

CREATE INDEX ix_status_checks_service ON status_checks (service);

CREATE TABLE suspicious_reports (
    id SERIAL NOT NULL, 
    ref VARCHAR(20) NOT NULL, 
    name VARCHAR(200) NOT NULL, 
    city VARCHAR(80) NOT NULL, 
    contact VARCHAR(120) NOT NULL, 
    status VARCHAR(12) NOT NULL, 
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
    PRIMARY KEY (id)
);

CREATE TABLE unapproved_institutions (
    id SERIAL NOT NULL, 
    name VARCHAR(200) NOT NULL, 
    city VARCHAR(80) NOT NULL, 
    notice VARCHAR(120) NOT NULL, 
    PRIMARY KEY (id)
);

CREATE TABLE institutions (
    id VARCHAR(20) NOT NULL, 
    aicte_id VARCHAR(20) NOT NULL, 
    name VARCHAR(200) NOT NULL, 
    city VARCHAR(80) NOT NULL, 
    state VARCHAR(80) NOT NULL, 
    region VARCHAR(8) NOT NULL, 
    category VARCHAR(120) NOT NULL, 
    established INTEGER NOT NULL, 
    land VARCHAR(10) NOT NULL, 
    lease_end DATE, 
    longest_course_years INTEGER NOT NULL, 
    intake INTEGER NOT NULL, 
    programmes JSON NOT NULL, 
    status VARCHAR(30) NOT NULL, 
    trust VARCHAR(200) NOT NULL, 
    lat FLOAT NOT NULL, 
    lng FLOAT NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(region) REFERENCES regions (id)
);

CREATE UNIQUE INDEX ix_institutions_aicte_id ON institutions (aicte_id);

CREATE INDEX ix_institutions_name ON institutions (name);

CREATE INDEX ix_institutions_region ON institutions (region);

CREATE TABLE applications (
    id VARCHAR(20) NOT NULL, 
    institution_id VARCHAR(20) NOT NULL, 
    type_id VARCHAR(30) NOT NULL, 
    cycle VARCHAR(10) NOT NULL, 
    submitted_on DATE NOT NULL, 
    stage VARCHAR(12) NOT NULL, 
    stage_entered_on DATE NOT NULL, 
    due_on DATE NOT NULL, 
    clock VARCHAR(10) NOT NULL, 
    paused_on DATE, 
    escalation_level INTEGER NOT NULL, 
    holder VARCHAR(80) NOT NULL, 
    region VARCHAR(8) NOT NULL, 
    deficiencies INTEGER NOT NULL, 
    risk FLOAT NOT NULL, 
    risk_reasons JSON NOT NULL, 
    outcome VARCHAR(4), 
    public_status VARCHAR(20) NOT NULL, 
    rules_version VARCHAR(20) NOT NULL, 
    submission_sha256 VARCHAR(64), 
    details JSON NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(institution_id) REFERENCES institutions (id), 
    FOREIGN KEY(region) REFERENCES regions (id), 
    FOREIGN KEY(type_id) REFERENCES application_types (id)
);

CREATE INDEX ix_applications_clock ON applications (clock);

CREATE INDEX ix_applications_due_on ON applications (due_on);

CREATE INDEX ix_applications_institution_id ON applications (institution_id);

CREATE INDEX ix_applications_region ON applications (region);

CREATE INDEX ix_applications_stage ON applications (stage);

CREATE TABLE drafts (
    id VARCHAR(40) NOT NULL, 
    institution_id VARCHAR(20) NOT NULL, 
    type_id VARCHAR(30) NOT NULL, 
    data JSON NOT NULL, 
    updated_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(institution_id) REFERENCES institutions (id)
);

CREATE INDEX ix_drafts_institution_id ON drafts (institution_id);

CREATE TABLE faculty (
    id VARCHAR(20) NOT NULL, 
    name VARCHAR(120) NOT NULL, 
    pan_hash VARCHAR(64) NOT NULL, 
    institution_id VARCHAR(20) NOT NULL, 
    designation VARCHAR(30) NOT NULL, 
    joined DATE NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(institution_id) REFERENCES institutions (id)
);

CREATE INDEX ix_faculty_institution_id ON faculty (institution_id);

CREATE INDEX ix_faculty_pan_hash ON faculty (pan_hash);

CREATE TABLE obligations (
    id VARCHAR(20) NOT NULL, 
    institution_id VARCHAR(20) NOT NULL, 
    kind VARCHAR(20) NOT NULL, 
    title TEXT NOT NULL, 
    clause VARCHAR(60) NOT NULL, 
    due_on DATE NOT NULL, 
    status VARCHAR(12) NOT NULL, 
    escalation_level INTEGER NOT NULL, 
    source VARCHAR(200) NOT NULL, 
    evidence VARCHAR(200), 
    PRIMARY KEY (id), 
    FOREIGN KEY(institution_id) REFERENCES institutions (id)
);

CREATE INDEX ix_obligations_institution_id ON obligations (institution_id);

CREATE TABLE users (
    id VARCHAR(40) NOT NULL, 
    name VARCHAR(120) NOT NULL, 
    email VARCHAR(160) NOT NULL, 
    phone VARCHAR(20) NOT NULL, 
    portal VARCHAR(12) NOT NULL, 
    role VARCHAR(40) NOT NULL, 
    region VARCHAR(8), 
    institution_id VARCHAR(20), 
    language VARCHAR(5) NOT NULL, 
    channels JSON NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(institution_id) REFERENCES institutions (id)
);

CREATE TABLE deficiencies (
    id SERIAL NOT NULL, 
    application_id VARCHAR(20) NOT NULL, 
    text TEXT NOT NULL, 
    clause VARCHAR(40) NOT NULL, 
    status VARCHAR(10) NOT NULL, 
    raised_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
    resolved_at TIMESTAMP WITHOUT TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(application_id) REFERENCES applications (id)
);

CREATE INDEX ix_deficiencies_application_id ON deficiencies (application_id);

CREATE TABLE documents (
    id VARCHAR(40) NOT NULL, 
    institution_id VARCHAR(20) NOT NULL, 
    application_id VARCHAR(20), 
    doc_kind VARCHAR(30) NOT NULL, 
    filename VARCHAR(200) NOT NULL, 
    storage_key VARCHAR(300) NOT NULL, 
    sha256 VARCHAR(64) NOT NULL, 
    size_bytes INTEGER NOT NULL, 
    pages INTEGER, 
    signed BOOLEAN NOT NULL, 
    signature JSON NOT NULL, 
    preflight JSON NOT NULL, 
    version INTEGER NOT NULL, 
    uploaded_by VARCHAR(120) NOT NULL, 
    uploaded_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(application_id) REFERENCES applications (id), 
    FOREIGN KEY(institution_id) REFERENCES institutions (id)
);

CREATE INDEX ix_documents_application_id ON documents (application_id);

CREATE INDEX ix_documents_institution_id ON documents (institution_id);

CREATE INDEX ix_documents_sha256 ON documents (sha256);

CREATE TABLE evc_panels (
    id SERIAL NOT NULL, 
    application_id VARCHAR(20) NOT NULL, 
    mode VARCHAR(10) NOT NULL, 
    shortlist JSON NOT NULL, 
    excluded JSON NOT NULL, 
    commitment VARCHAR(64) NOT NULL, 
    committed_round INTEGER NOT NULL, 
    randomness VARCHAR(64), 
    chosen JSON NOT NULL, 
    verified BOOLEAN NOT NULL, 
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
    drawn_at TIMESTAMP WITHOUT TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(application_id) REFERENCES applications (id)
);

CREATE INDEX ix_evc_panels_application_id ON evc_panels (application_id);

CREATE TABLE history_events (
    id SERIAL NOT NULL, 
    application_id VARCHAR(20) NOT NULL, 
    at VARCHAR(19) NOT NULL, 
    actor VARCHAR(120) NOT NULL, 
    role VARCHAR(80) NOT NULL, 
    action TEXT NOT NULL, 
    note TEXT, 
    rule_ref VARCHAR(60), 
    PRIMARY KEY (id), 
    FOREIGN KEY(application_id) REFERENCES applications (id)
);

CREATE INDEX ix_history_events_application_id ON history_events (application_id);

CREATE TABLE visit_photos (
    id SERIAL NOT NULL, 
    application_id VARCHAR(20) NOT NULL, 
    filename VARCHAR(200) NOT NULL, 
    sha256 VARCHAR(64) NOT NULL, 
    lat FLOAT, 
    lng FLOAT, 
    taken_at VARCHAR(19), 
    distance_m INTEGER, 
    verdict VARCHAR(10) NOT NULL, 
    uploaded_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(application_id) REFERENCES applications (id)
);

CREATE INDEX ix_visit_photos_application_id ON visit_photos (application_id);

INSERT INTO alembic_version (version_num) VALUES ('0001_baseline') RETURNING alembic_version.version_num;

-- Running upgrade 0001_baseline -> 0002_row_security

DO $$ BEGIN
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'anumati_app') THEN CREATE ROLE anumati_app NOLOGIN; END IF;
END $$;

GRANT USAGE ON SCHEMA public TO anumati_app;

GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO anumati_app;

GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO anumati_app;

REVOKE INSERT, UPDATE, DELETE ON alembic_version FROM anumati_app;

REVOKE UPDATE, DELETE, TRUNCATE ON audit_log FROM anumati_app;

ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO anumati_app;

ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT USAGE, SELECT ON SEQUENCES TO anumati_app;

CREATE OR REPLACE FUNCTION anumati_sees_application(inst text, app_region text) RETURNS boolean
LANGUAGE sql STABLE AS $$
  SELECT CASE coalesce(current_setting('anumati.portal', true), '')
    WHEN 'system' THEN true
    WHEN 'public' THEN true            -- public pages publish aggregates and verify letters only
    WHEN 'institution' THEN inst = current_setting('anumati.institution_id', true)
    WHEN 'aicte' THEN coalesce(current_setting('anumati.region', true), '') = '' OR app_region = coalesce(current_setting('anumati.region', true), '')
    ELSE false END
$$;

CREATE OR REPLACE FUNCTION anumati_sees_institution_data(inst text) RETURNS boolean
LANGUAGE sql STABLE AS $$
  SELECT CASE coalesce(current_setting('anumati.portal', true), '')
    WHEN 'system' THEN true
    WHEN 'aicte' THEN true
    WHEN 'institution' THEN inst = current_setting('anumati.institution_id', true)
    ELSE false END                    -- documents, drafts, obligations and faculty are never public
$$;

ALTER TABLE applications ENABLE ROW LEVEL SECURITY;

CREATE POLICY anumati_scope ON applications FOR ALL TO anumati_app USING (anumati_sees_application(institution_id, region)) WITH CHECK (anumati_sees_application(institution_id, region));

ALTER TABLE history_events ENABLE ROW LEVEL SECURITY;

CREATE POLICY anumati_scope ON history_events FOR ALL TO anumati_app USING (EXISTS (SELECT 1 FROM applications a WHERE a.id = history_events.application_id)) WITH CHECK (EXISTS (SELECT 1 FROM applications a WHERE a.id = history_events.application_id));

ALTER TABLE deficiencies ENABLE ROW LEVEL SECURITY;

CREATE POLICY anumati_scope ON deficiencies FOR ALL TO anumati_app USING (EXISTS (SELECT 1 FROM applications a WHERE a.id = deficiencies.application_id)) WITH CHECK (EXISTS (SELECT 1 FROM applications a WHERE a.id = deficiencies.application_id));

ALTER TABLE evc_panels ENABLE ROW LEVEL SECURITY;

CREATE POLICY anumati_scope ON evc_panels FOR ALL TO anumati_app USING (EXISTS (SELECT 1 FROM applications a WHERE a.id = evc_panels.application_id)) WITH CHECK (EXISTS (SELECT 1 FROM applications a WHERE a.id = evc_panels.application_id));

ALTER TABLE visit_photos ENABLE ROW LEVEL SECURITY;

CREATE POLICY anumati_scope ON visit_photos FOR ALL TO anumati_app USING (EXISTS (SELECT 1 FROM applications a WHERE a.id = visit_photos.application_id)) WITH CHECK (EXISTS (SELECT 1 FROM applications a WHERE a.id = visit_photos.application_id));

ALTER TABLE documents ENABLE ROW LEVEL SECURITY;

CREATE POLICY anumati_scope ON documents FOR ALL TO anumati_app USING (anumati_sees_institution_data(institution_id)) WITH CHECK (anumati_sees_institution_data(institution_id));

ALTER TABLE drafts ENABLE ROW LEVEL SECURITY;

CREATE POLICY anumati_scope ON drafts FOR ALL TO anumati_app USING (anumati_sees_institution_data(institution_id)) WITH CHECK (anumati_sees_institution_data(institution_id));

ALTER TABLE obligations ENABLE ROW LEVEL SECURITY;

CREATE POLICY anumati_scope ON obligations FOR ALL TO anumati_app USING (anumati_sees_institution_data(institution_id)) WITH CHECK (anumati_sees_institution_data(institution_id));

ALTER TABLE faculty ENABLE ROW LEVEL SECURITY;

CREATE POLICY anumati_scope ON faculty FOR ALL TO anumati_app USING (anumati_sees_institution_data(institution_id)) WITH CHECK (anumati_sees_institution_data(institution_id));

ALTER TABLE notifications ENABLE ROW LEVEL SECURITY;

CREATE POLICY anumati_scope ON notifications FOR ALL TO anumati_app USING (CASE coalesce(current_setting('anumati.portal', true), '') WHEN 'system' THEN true WHEN 'aicte' THEN true WHEN 'institution' THEN audience = 'institution' AND institution_id = current_setting('anumati.institution_id', true) ELSE false END) WITH CHECK (true);

ALTER TABLE audit_log ENABLE ROW LEVEL SECURITY;

CREATE POLICY anumati_scope ON audit_log FOR ALL TO anumati_app USING (CASE coalesce(current_setting('anumati.portal', true), '') WHEN 'system' THEN true WHEN 'public' THEN true WHEN 'institution' THEN ref = 'VAULT-' || current_setting('anumati.institution_id', true) OR EXISTS (SELECT 1 FROM applications a WHERE a.id = audit_log.ref) WHEN 'aicte' THEN coalesce(current_setting('anumati.region', true), '') = '' OR ref NOT LIKE 'ANU-%' OR EXISTS (SELECT 1 FROM applications a WHERE a.id = audit_log.ref) ELSE false END) WITH CHECK (CASE coalesce(current_setting('anumati.portal', true), '') WHEN 'system' THEN true WHEN 'public' THEN true WHEN 'institution' THEN ref = 'VAULT-' || current_setting('anumati.institution_id', true) OR EXISTS (SELECT 1 FROM applications a WHERE a.id = audit_log.ref) WHEN 'aicte' THEN coalesce(current_setting('anumati.region', true), '') = '' OR ref NOT LIKE 'ANU-%' OR EXISTS (SELECT 1 FROM applications a WHERE a.id = audit_log.ref) ELSE false END);

CREATE OR REPLACE FUNCTION anumati_forbid_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'audit_log is append-only'; END $$;

CREATE TRIGGER audit_log_append_only BEFORE UPDATE OR DELETE ON audit_log FOR EACH ROW EXECUTE FUNCTION anumati_forbid_change();

UPDATE alembic_version SET version_num='0002_row_security' WHERE alembic_version.version_num = '0001_baseline';

-- Running upgrade 0002_row_security -> 0003_obligation_audit

DROP POLICY IF EXISTS anumati_scope ON audit_log;

CREATE POLICY anumati_scope ON audit_log FOR ALL TO anumati_app USING (CASE coalesce(current_setting('anumati.portal', true), '') WHEN 'system' THEN true WHEN 'public' THEN true WHEN 'institution' THEN ref = 'VAULT-' || current_setting('anumati.institution_id', true) OR EXISTS (SELECT 1 FROM applications a WHERE a.id = audit_log.ref) OR EXISTS (SELECT 1 FROM obligations o WHERE o.id = audit_log.ref) WHEN 'aicte' THEN coalesce(current_setting('anumati.region', true), '') = '' OR ref NOT LIKE 'ANU-%' OR EXISTS (SELECT 1 FROM applications a WHERE a.id = audit_log.ref) ELSE false END) WITH CHECK (CASE coalesce(current_setting('anumati.portal', true), '') WHEN 'system' THEN true WHEN 'public' THEN true WHEN 'institution' THEN ref = 'VAULT-' || current_setting('anumati.institution_id', true) OR EXISTS (SELECT 1 FROM applications a WHERE a.id = audit_log.ref) OR EXISTS (SELECT 1 FROM obligations o WHERE o.id = audit_log.ref) WHEN 'aicte' THEN coalesce(current_setting('anumati.region', true), '') = '' OR ref NOT LIKE 'ANU-%' OR EXISTS (SELECT 1 FROM applications a WHERE a.id = audit_log.ref) ELSE false END);

UPDATE alembic_version SET version_num='0003_obligation_audit' WHERE alembic_version.version_num = '0002_row_security';

-- Running upgrade 0003_obligation_audit -> 0004_institutional_record

ALTER TABLE institutions ADD COLUMN profile JSON DEFAULT '{}' NOT NULL;

ALTER TABLE users ADD COLUMN active BOOLEAN DEFAULT true NOT NULL;

ALTER TABLE documents ADD COLUMN review_status VARCHAR(24) DEFAULT 'uploaded' NOT NULL;

ALTER TABLE documents ADD COLUMN review_note TEXT;

ALTER TABLE documents ADD COLUMN reviewed_by VARCHAR(120);

ALTER TABLE documents ADD COLUMN reviewed_at TIMESTAMP WITHOUT TIME ZONE;

ALTER TABLE faculty ADD COLUMN department VARCHAR(120) DEFAULT '' NOT NULL;

ALTER TABLE faculty ADD COLUMN qualification VARCHAR(40) DEFAULT '' NOT NULL;

ALTER TABLE faculty ADD COLUMN employment VARCHAR(12) DEFAULT 'Regular' NOT NULL;

ALTER TABLE faculty ADD COLUMN status VARCHAR(10) DEFAULT 'Active' NOT NULL;

ALTER TABLE faculty ADD COLUMN verification VARCHAR(12) DEFAULT 'Pending' NOT NULL;

ALTER TABLE deficiencies ADD COLUMN stage VARCHAR(12) DEFAULT 'scrutiny' NOT NULL;

CREATE TABLE campuses (
    id VARCHAR(24) NOT NULL, 
    institution_id VARCHAR(20) NOT NULL, 
    name VARCHAR(120) NOT NULL, 
    address TEXT NOT NULL, 
    city VARCHAR(80) NOT NULL, 
    state VARCHAR(80) NOT NULL, 
    pincode VARCHAR(10) NOT NULL, 
    lat FLOAT, 
    lng FLOAT, 
    land_acres FLOAT NOT NULL, 
    ownership VARCHAR(10) NOT NULL, 
    deed_no VARCHAR(60) NOT NULL, 
    lease_start DATE, 
    lease_end DATE, 
    is_main BOOLEAN NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(institution_id) REFERENCES institutions (id)
);

CREATE TABLE spaces (
    id SERIAL NOT NULL, 
    institution_id VARCHAR(20) NOT NULL, 
    campus_id VARCHAR(24) NOT NULL, 
    category VARCHAR(16) NOT NULL, 
    kind VARCHAR(40) NOT NULL, 
    name VARCHAR(120) NOT NULL, 
    building VARCHAR(80) NOT NULL, 
    area_sqm FLOAT NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(institution_id) REFERENCES institutions (id), 
    FOREIGN KEY(campus_id) REFERENCES campuses (id)
);

CREATE TABLE certificates (
    id VARCHAR(24) NOT NULL, 
    institution_id VARCHAR(20) NOT NULL, 
    campus_id VARCHAR(24), 
    kind VARCHAR(60) NOT NULL, 
    number VARCHAR(60) NOT NULL, 
    issued_by VARCHAR(160) NOT NULL, 
    issued_on DATE, 
    valid_until DATE, 
    document_id VARCHAR(40), 
    verification VARCHAR(12) NOT NULL, 
    verified_by VARCHAR(120), 
    verified_at TIMESTAMP WITHOUT TIME ZONE, 
    note TEXT, 
    reminded JSON NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(institution_id) REFERENCES institutions (id), 
    FOREIGN KEY(campus_id) REFERENCES campuses (id), 
    FOREIGN KEY(document_id) REFERENCES documents (id)
);

CREATE TABLE programmes (
    id VARCHAR(24) NOT NULL, 
    institution_id VARCHAR(20) NOT NULL, 
    department VARCHAR(120) NOT NULL, 
    name VARCHAR(160) NOT NULL, 
    level VARCHAR(10) NOT NULL, 
    duration_years INTEGER NOT NULL, 
    approved_intake INTEGER NOT NULL, 
    status VARCHAR(10) NOT NULL, 
    since INTEGER NOT NULL, 
    x_category BOOLEAN NOT NULL, 
    accreditation JSON NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(institution_id) REFERENCES institutions (id)
);

CREATE TABLE leaders (
    id SERIAL NOT NULL, 
    institution_id VARCHAR(20) NOT NULL, 
    name VARCHAR(120) NOT NULL, 
    position VARCHAR(60) NOT NULL, 
    department VARCHAR(120) NOT NULL, 
    email VARCHAR(160) NOT NULL, 
    is_signatory BOOLEAN NOT NULL, 
    since DATE NOT NULL, 
    until DATE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(institution_id) REFERENCES institutions (id)
);

CREATE TABLE members (
    id SERIAL NOT NULL, 
    institution_id VARCHAR(20) NOT NULL, 
    name VARCHAR(120) NOT NULL, 
    email VARCHAR(160) NOT NULL, 
    role VARCHAR(40) NOT NULL, 
    user_id VARCHAR(40), 
    active BOOLEAN NOT NULL, 
    added_by VARCHAR(120) NOT NULL, 
    added_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
    deactivated_at TIMESTAMP WITHOUT TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(institution_id) REFERENCES institutions (id)
);

CREATE TABLE field_inspections (
    id VARCHAR(24) NOT NULL, 
    application_id VARCHAR(20) NOT NULL, 
    inspector_id VARCHAR(40) NOT NULL, 
    inspector_name VARCHAR(120) NOT NULL, 
    assigned_by VARCHAR(120) NOT NULL, 
    assigned_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
    mode VARCHAR(10) NOT NULL, 
    status VARCHAR(12) NOT NULL, 
    items JSON NOT NULL, 
    video_url VARCHAR(300) NOT NULL, 
    started_at TIMESTAMP WITHOUT TIME ZONE, 
    submitted_at TIMESTAMP WITHOUT TIME ZONE, 
    signature JSON NOT NULL, 
    report_sha256 VARCHAR(64), 
    PRIMARY KEY (id), 
    FOREIGN KEY(application_id) REFERENCES applications (id)
);

CREATE TABLE verifications (
    id SERIAL NOT NULL, 
    institution_id VARCHAR(20) NOT NULL, 
    subject VARCHAR(20) NOT NULL, 
    subject_id VARCHAR(40) NOT NULL, 
    subject_label VARCHAR(200) NOT NULL, 
    outcome VARCHAR(12) NOT NULL, 
    note TEXT NOT NULL, 
    source VARCHAR(20) NOT NULL, 
    checked_by VARCHAR(120) NOT NULL, 
    checked_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(institution_id) REFERENCES institutions (id)
);

CREATE TABLE regulatory_actions (
    id SERIAL NOT NULL, 
    institution_id VARCHAR(20) NOT NULL, 
    application_id VARCHAR(20), 
    kind VARCHAR(30) NOT NULL, 
    detail TEXT NOT NULL, 
    reason TEXT NOT NULL, 
    decided_by VARCHAR(120) NOT NULL, 
